  // 03 — Default product assets
  // ────────────────────────────────────────────────────────────────────────
  const DEFAULT_MASCOT_ASSET_ID = 'asset-default-mascot';
  const STANDARD_AKARI_MASCOT = Object.freeze({
    name: 'たくどん',
    value: '',
    fg: '#f5a000',
    kind: 'image',
    assetId: DEFAULT_MASCOT_ASSET_ID,
    w: 180,
    h: 180,
  });
  const DEFAULT_MASCOT_SHA256 =
    '7f6f2d938d207db2b8b47becbd177d33c2c1adda11aafbefaf96ab4cba74357f';
  const DEFAULT_MASCOT_PNG_BASE64 =
    '';
  let DEFAULT_MASCOT_ASSET_RECORD = null;
  function defaultMascotAssetRecord() {
    if (DEFAULT_MASCOT_ASSET_RECORD) return DEFAULT_MASCOT_ASSET_RECORD;
    const bytes = decodeBase64(DEFAULT_MASCOT_PNG_BASE64);
    if (bytes.length !== 5476 || sha256Fallback(bytes) !== DEFAULT_MASCOT_SHA256)
      throw new AkariError('F508', 'あかりに 入っている キャラクターの 絵が こわれています。先生に 知らせてください');
    DEFAULT_MASCOT_ASSET_RECORD = makeImmutableAssetRecord({
      id: DEFAULT_MASCOT_ASSET_ID,
      kind: 'image',
      mime: 'image/png',
      sha256: DEFAULT_MASCOT_SHA256,
      bytes,
      meta: { width: 180, height: 180 },
    });
    return DEFAULT_MASCOT_ASSET_RECORD;
  }
  function makeDefaultAssetStore() {
    return new AssetStore([defaultMascotAssetRecord()]);
  }
  function withDefaultMascotAsset(project, store) {
    if (
      !collectReachableAssetIds(project).has(DEFAULT_MASCOT_ASSET_ID) ||
      store.has(DEFAULT_MASCOT_ASSET_ID)
    )
      return store;
    const next = new AssetStore(store.snapshotRefs());
    next.addImmutable(defaultMascotAssetRecord());
    return next;
  }

